  "why.anthropicSEconomic": "<0>Anthropic ཀྱི་དཔལ་འབྱོར་ཐོ་ཆད་ (<1/>)<\/0> ལས་ལས་ཀའི་འགོ་ཐོག་པ་རྣམས་ཀྱིས་རང་གི་ལས་ཀ་མང་ཤོས་ AI ཡིས་བྱེད་ཐུབ་པར་མཐོང་བ་རྙེད།",
  "why.anthropicSEconomic2": "<0>Anthropic ཀྱི་དཔལ་འབྱོར་སྲིད་ཇུས་ཀྱི་བཀོད་པ་ (<1/>)<\/0> ཀྱིས་ཚོང་ལས་ཁང་རྣམས་ལ་མི་བཅད་པའི་ཚབ་ཏུ་མི་རྣམས་བསླབ་སྦྱོང་ཡང་བསྐྱར་དང་གནས་སྒྱུར་བྱེད་པར་ཞུ།",
  "why.anthropicSReview": "<0>Anthropic ཀྱི་བསླབ་སྦྱོང་གསར་བསྐྱར་གྱི་ཁུངས་སྒྲུབ་ཀྱི་བརྟག་དཔྱད་ (<1/>)<\/0> ཀྱིས་ལས་བྱེད་ཁང་དང་འབྲེལ་བ་དང་ཁྱད་ལས་རྣམ་པའི་ལས་རིམ་རྣམས་ཁྱད་པར་ཡག་ཤོས་རྙེད།",
  "why.askSimpleFive": "རེ་བ་ནི་སྟབས་བདེ། འགོ་འཛུགས་ཆེད་ Claude ཡི་འདུག་ས་ལྔ། གསར་གཏོད་པས་དེ་དག་ནུས་པ་ལྡན་ཞིང་སྤྲོ་བ་ཅན་གྱི་མི་རྣམས་ཀྱིས་གང་ན། ང་ཚོས་ AI ཡིས་བསམ་བློ་བཟང་པོས་ཇི་ལྟར་མཛེས་པའི་དངོས་པོ་བཟོ་ཐུབ་པ་སྟོན་ངེས།",
  "why.context": "རྒྱབ་ལྗོངས།",
  "why.designersEngineers": "སྒྲིག་འདོན་པ་དང་ལག་རྩལ་པ་རྣམས་ལ།",
  "why.everyItemBelow": "འོག་གི་དོན་ཚན་རེ་རེ་ནི་འཆར་གཞི་ཡིན་པ་འམ་ད་དུང་གསལ་བསྒྲགས་མ་བྱས་པ་ཡིན། འདིར་གང་ཡང་མཐུན་མ་སོང་ལ་གྲངས་ཀ་གང་ཡང་ཁས་མི་ལེན།",
  "why.founderWentFrom": "གསར་གཏོད་པ་གཅིག་གིས་སྔོན་རྩེད་ནས་ 0.6.1 བར་ཉིན་ <0/> ནང་སླེབས། དམིགས་ཡུལ་གཅིག་ལ་བརྩོན་པའི་ཚོགས་པ་ལྔས་ཅི་ཞིག་ཐུབ་བསམས་ཤིག",
