  "why.fromBackers": "རྒྱབ་སྐྱོར་བ་རྣམས་ནས།",
  "why.fullyDisclosedAi": "ཆ་ཚང་གསལ་བཤད་བྱས་པའི་ AI ཡིས་བཟོས་པའི་རྩེད་མོ་ཞིག ཁོ་ལ་རྩེ་མཁན་གྱིས་ཞིབ་བཤེར་བྱེད་ཐུབ་པའི་དམིགས་ཡུལ་ཡོད་ཅིང་ Unreal Engine 5 ལ་འཕོ་རྒྱུའི་འཆར་གཞི་ཡོད། (ལམ་ཁྲའི་སྐབས་ 3།)",
  "why.fullyDocumentedExample": "འཁོར་ཆས་ནས་རྩེད་མོའི་བར་ཁྲིད་མཁན་ AI ཡིས་བཟོ་བའི་ཆ་ཚང་ཟིན་ཐོ་བྱས་པའི་དཔེ་མཚོན། (མཛོད་པ། ལས་འགན་ཐོ། གཏན་འཇགས་པར་གཞི་རེ་རེ་ཉར་ཡོད།) དང་། AI ཀྱི་ཕན་འབྲས་ཀྱིས་དེས་ལས་ཀ་བརླག་པའི་མི་རྣམས་ལ་དངུལ་འཇོག་ཐུབ་པའི་ཐབས་གཅིག་གི་ཆུང་ཆུང་ལག་ལེན་གྱི་ཚོད་ལྟ།",
  "why.fundingGoalAnnounced": "དངུལ་སྒྲུབ་ཀྱི་དམིགས་ཡུལ། གསལ་བསྒྲགས་བྱེད་རྒྱུ།",
  "why.kickstarterRoadmapPhase": "Kickstarter (ལམ་ཁྲའི་སྐབས་ 5) ནི་སྤྱི་ཚོགས་ཀྱི་དངུལ་སྒྲུབ་སྐབས་དང་པོ་ཡིན། དེའི་དངུལ་ཡོད་ན། AI ཀྱིས་ལས་ཀ་བརླག་པའི་གསར་སྤེལ་པ་དང་པར་རིས་སྒྲིག་འདོན་པ་དང་པོ་རྣམས་བསྡུ་ལེན་བྱེད་པར་སྤྱོད་པར་བསམ། (སྐབས་ 6) ཁོང་ཚོས་དེ་ནས་ AI ཡིས་བཟོས་པའི་རྒྱུ་ཆ་རྣམས་རེ་རེ་ནས་ཚབ་བྱེད། <0>སྐབས་དང་པོའི་དངུལ་གྱིས་གང་གི་རིན་སྤྲོད། ལས་འགན་རེ་རེ་ལྟར། གསལ་བསྒྲགས་བྱེད་རྒྱུ།<\/0>",
  "why.linksContextOnly": "སྦྲེལ་ཐག་རྣམས་རྒྱབ་ལྗོངས་ཀྱི་ཆེད་ཙམ་ཡིན་ལ་ཁས་ལེན་མི་སྟོན།",
  "why.n06WhyMatters": "06 · ཅིའི་ཕྱིར་གལ་ཆེ།",
  "why.orion81Tests": "Orion-81 ཡིས་བསམ་འཆར་དེའི་ཆུང་ཆུང་གི་རྣམ་པ་གཅིག་ལ་ཚོད་ལྟ་བྱེད། དེ་ནི་འཆར་གཞི་ཡིན་ལ་ད་དུང་གླ་མི་མེད།",
  "why.plannedPaidCredited": "འཆར་གཞི། ཡོང་སྒོ་ཡོད་ཚད་ལྟར་གླ་ཆ་དང་མིང་ཐོག་ཞབས་ཏོག་གི་ལས་ཀས་ AI ཡིས་བཟོས་པའི་རྒྱུ་ཆ་རྣམས་རེ་རེ་ནས་ཚབ་བྱེད།",
  "why.publishersEngineMakers": "པར་འདེབས་ཁང་དང་འཁོར་ཆས་བཟོ་མཁན་རྣམས་ལ།",
  "why.routesThatExist": "Anthropic ཀྱི་སྤྱི་ཡོངས་ལས་རིམ་ནང་ཡོད་པའི་ལམ་ལ། Claude for Startups (ཁྱད་དངུལ་དང་ Applied AI ལས་ཡུན་གྱི་འདྲི་རྩད།) དང་ Claude Founder House ཚོགས་འདུ་རྣམས་ཡོད། Orion-81 ཡང་ AI ཡིས་དངུལ་འཇོག་པའི་ལས་ཀ་གསར་འཇུག་ལ་ཞིབ་འཇུག་བྱེད་མཁན་རྣམས་ཀྱི་ཞིབ་བཤེར་ས་ཆ་ཞིག་ཏུ་འགྱུར་སྲིད། མཐུན་འཐད་དམ་ཁས་ལེན་གང་ཡང་མེད།",
  "why.studyingAiFunded": "AI ཡིས་དངུལ་འཇོག་པའི་ལས་ཀ་གསར་འཇུག་ལ་ཞིབ་འཇུག་བྱེད་ཀྱི་ཡོད་དམ། <0>འབྲེལ་བའི་ཁ་བརྡ་མི་རིང་བར་འབྱུང་།<\/0>",
